// Verify X-Signature = HMAC-SHA256(N8N_SHARED_SECRET, raw request body).
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
if (!secret) { throw new Error('N8N_SHARED_SECRET is not set'); }
const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-signature'] || headers['X-Signature'];
let rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body));
const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
if (!sig || expected !== sig) { throw new Error('invalid signature'); }
const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;
return [{ json: payload }];

// Multilingual return-request acknowledgement (customer) + internal ops alert.
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const sym = { EUR: '€', USD: '$', GBP: '£' }[d.currency] || (d.currency ? d.currency + ' ' : '');
const money = (v) => sym + Number(v || 0).toFixed(2);

const t = {
  en: { subject: `We received your return request for order ${d.order_number}`, hi: `Hi ${d.first_name || ''},`, intro: 'We have received your return request and our team is reviewing it. We will email you with the decision shortly.', reason: 'Reason', view: 'View your return', thanks: 'Thank you for your patience — Glitchy.' },
  it: { subject: `Abbiamo ricevuto la tua richiesta di reso per l’ordine ${d.order_number}`, hi: `Ciao ${d.first_name || ''},`, intro: 'Abbiamo ricevuto la tua richiesta di reso e il nostro team la sta esaminando. Ti scriveremo a breve con la decisione.', reason: 'Motivo', view: 'Vedi il tuo reso', thanks: 'Grazie per la pazienza — Glitchy.' },
  fr: { subject: `Nous avons reçu votre demande de retour pour la commande ${d.order_number}`, hi: `Bonjour ${d.first_name || ''},`, intro: 'Nous avons bien reçu votre demande de retour et notre équipe l’examine. Nous vous informerons de la décision sous peu.', reason: 'Motif', view: 'Voir votre retour', thanks: 'Merci de votre patience — Glitchy.' }
}[lang];
const L = t || { subject: `We received your return request for order ${d.order_number}`, hi: `Hi ${d.first_name || ''},`, intro: 'We have received your return request and our team is reviewing it.', reason: 'Reason', view: 'View your return', thanks: 'Thank you for your patience — Glitchy.' };

const btn = d.return_url ? `<p style="margin:18px 0"><a href="${d.return_url}" style="background:#111;color:#fff;padding:10px 18px;text-decoration:none;border-radius:6px;display:inline-block">${L.view}</a></p>` : '';
const customerHtml = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${L.subject}</h2>
<p>${L.hi}</p>
<p>${L.intro}</p>
${d.reason ? `<p><strong>${L.reason}:</strong> ${d.reason}</p>` : ''}
${btn}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

// Internal ops email (always English, operational).
const opsSubject = `[Return Requested] Order ${d.order_number}`;
const opsHtml = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#222">
<h3>New return request</h3>
<ul>
<li><strong>Order:</strong> ${d.order_number}</li>
<li><strong>Customer:</strong> ${d.first_name || ''} &lt;${p.recipient}&gt;</li>
<li><strong>Status:</strong> ${d.status || 'requested'}</li>
<li><strong>Refund amount:</strong> ${money(d.refund_amount)}</li>
<li><strong>Reason:</strong> ${d.reason || '-'}</li>
<li><strong>Admin note:</strong> ${d.admin_note || '-'}</li>
</ul>
${d.return_url ? `<p><a href="${d.return_url}">Open in admin</a></p>` : ''}
</div>`;

return [{ json: {
  customer_to: p.recipient,
  customer_subject: L.subject,
  customer_html: customerHtml,
  ops_to: $env.ADMIN_NOTIFY_EMAIL,
  ops_subject: opsSubject,
  ops_html: opsHtml
} }];
